const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const basePremiumOf = (item: Item): number =>
  item.type === "sword" ? 100 : 0;

const policyBasePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const quote = (step: QuoteStep): QuoteResult => {
  const basePremium = policyBasePremiumOf(step.items);
  const firstInsuranceSurcharge = percentOf(
    basePremium,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );

  return {
    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
  };
};
